namespace RonSijm.FluidHumidifier.Factories.Braket;

public class JobFactory(string resourceName = null, Action<Humidifier.Braket.Job> factoryAction = null) : ResourceFactory<Humidifier.Braket.Job>(resourceName)
{

    internal List<InnerJobInputFileConfigFactory> InputDataConfigFactories { get; set; } = [];

    internal InnerJobAlgorithmSpecificationFactory AlgorithmSpecificationFactory { get; set; }

    internal InnerJobInstanceConfigFactory InstanceConfigFactory { get; set; }

    internal InnerJobJobStoppingConditionFactory StoppingConditionFactory { get; set; }

    internal InnerJobJobOutputDataConfigFactory OutputDataConfigFactory { get; set; }

    internal InnerJobJobCheckpointConfigFactory CheckpointConfigFactory { get; set; }

    internal InnerJobDeviceConfigFactory DeviceConfigFactory { get; set; }

    protected override Humidifier.Braket.Job Create()
    {
        var jobResult = CreateJob();
        factoryAction?.Invoke(jobResult);

        return jobResult;
    }

    private Humidifier.Braket.Job CreateJob()
    {
        var jobResult = new Humidifier.Braket.Job
        {
            GivenName = InputResourceName,
        };

        return jobResult;
    }
    public override void CreateChildren(Humidifier.Braket.Job result)
    {
        base.CreateChildren(result);

        result.InputDataConfig = InputDataConfigFactories.Any() ? InputDataConfigFactories.Select(x => x.Build()).ToList() : null;
        result.AlgorithmSpecification ??= AlgorithmSpecificationFactory?.Build();
        result.InstanceConfig ??= InstanceConfigFactory?.Build();
        result.StoppingCondition ??= StoppingConditionFactory?.Build();
        result.OutputDataConfig ??= OutputDataConfigFactory?.Build();
        result.CheckpointConfig ??= CheckpointConfigFactory?.Build();
        result.DeviceConfig ??= DeviceConfigFactory?.Build();
    }

} // End Of Class

